package com.shiphappens.logistics.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="shipments") public class Shipment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="shipment_number") private String shipmentNumber; @Column(name="tracking_number") private String trackingNumber; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private LogisticsOrder order; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @Enumerated(EnumType.STRING) private Statuses.ShipmentStatus status=Statuses.ShipmentStatus.CREATED; @Column(name="created_at") private Instant createdAt; @PrePersist void created(){createdAt=Instant.now();} public Long getId(){return id;} public String getShipmentNumber(){return shipmentNumber;} public void setShipmentNumber(String v){shipmentNumber=v;} public String getTrackingNumber(){return trackingNumber;} public void setTrackingNumber(String v){trackingNumber=v;} @JsonIgnore public LogisticsOrder getOrder(){return order;} public void setOrder(LogisticsOrder v){order=v;} @JsonIgnore public Warehouse getWarehouse(){return warehouse;} public void setWarehouse(Warehouse v){warehouse=v;} public Statuses.ShipmentStatus getStatus(){return status;} public void setStatus(Statuses.ShipmentStatus v){status=v;} public Instant getCreatedAt(){return createdAt;} }
